pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the sender and the amount sent
    function testFuzz_property(address sender, uint256 amount) public {
        // keep sender non-zero and amount in a reasonable range to avoid overflow/edge weirdness
        vm.assume(sender != address(0));
        // bound amount so fuzzer searches useful range (0 .. 20 ether)
        amount = bound(amount, 0, 20 ether);

        // fund the sender so they can send the amount
        vm.deal(sender, amount);

        // advance time to ensure block.timestamp > pastBlockTime initially (pastBlockTime starts 0)
        vm.warp(block.timestamp + 1);

        // perform the payable fallback call from sender with fuzzed amount
        bool ok;
        vm.prank(sender);
        try c.f{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: Reference contract accepts the call iff msg.value == 10 ether (so ok==true exactly when amount==10 ether)
        // We assert that for the reference: ok == (amount == 10 ether)
        assertTrue(ok == (amount == 10 ether));
    }
}

