pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz param: caller address (will be funded/pranked) and a block timestamp gap flag
    // We need at least one fuzzed parameter; use an address and a uint256 to control block number.
    function testFuzz_property(address caller, uint256 warpOffset) public {
        // keep caller as non-zero and not the contract itself
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        // fund the caller so it can send 10 ether
        vm.deal(caller, 20 ether);

        // Make sure we can control block timestamp; bound warpOffset to small range to keep test meaningful
        uint256 smallOffset = bound(warpOffset, 0, 5);

        // First call: set pastBlockTime to current timestamp if allowed
        vm.warp(block.timestamp + 1 + smallOffset); // advance time at least 1
        vm.prank(caller);
        c.f{value: 10 ether}();

        // Record pastBlockTime after first call
        uint256 t1 = c.pastBlockTime();

        // Now perform a second call in the SAME block (no warp) by the same caller
        // This is the distinguishing input: two calls within same block.
        vm.prank(caller);
        c.f{value: 10 ether}();

        // Read pastBlockTime after the second call
        uint256 t2 = c.pastBlockTime();

        // GENERAL RULE (single assertion): In the correct contract, a second call made in the same block
        // must NOT increase pastBlockTime (it must remain equal to the value set by the first call)
        // The mutant (which removed the time check) will update pastBlockTime to the same block.timestamp again
        // but since both calls are in same block the correct contract ensures t2 == t1; the mutant can make t2 == block.timestamp
        // which may differ because the mutant updates regardless — the fuzzer can find such a case.
        assertTrue(t2 == t1);
    }
}

