        uint256 ts = block.timestamp;
        vm.warp(ts);

        // First call in this timestamp/block: send 10 ether again to possibly update pastBlockTime in reference
        vm.prank(caller);
        c.f{value: 10 ether}();

        // Capture balance after first call
