pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: caller address and a block number that makes the conditional transfer trigger (i.e., block.number % 15 == 0)
    // Also fuzz a timestamp increment to ensure block.timestamp > pastBlockTime
    function testFuzz_property(address caller, uint256 targetBlock, uint256 timeAdvance) public {
        vm.assume(caller != address(0));
        // bound targetBlock to a reasonable range and ensure it can be >= current block
        targetBlock = bound(targetBlock, block.number, block.number + 1000);
        // ensure timeAdvance is at least 1 to satisfy require(block.timestamp > pastBlockTime)
        timeAdvance = bound(timeAdvance, 1, 1 days);

        // We need an adversarial callee to receive the transfer and not revert (use a normal address with code)
        // Deploy a helper that accepts ether and does NOT revert; it does nothing special but exists as a contract so transfer behaves differently than to an EOA
        Receiver recv = new Receiver();

        // Fund caller so it can send 10 ether
        vm.deal(caller, 20 ether);
        // Advance time so timestamp increases relative to pastBlockTime (initial 0)
        vm.warp(block.timestamp + timeAdvance);

        // Advance block number to the targetBlock
        // If targetBlock is already current, this is noop; otherwise roll forward
        if (targetBlock > block.number) vm.roll(targetBlock);

        // Make sure block.number % 15 == 0 to hit the transfer branch sometimes; if not, adjust by rolling forward up to 14 blocks
        if (block.number % 15 != 0) {
            uint256 offset = (15 - (block.number % 15));
            vm.roll(block.number + offset);
        }

        // Now block.number % 15 == 0. The test will call fallback by sending 10 ether from caller.
        // Use prank so msg.sender is caller. Use the receiver contract as the msg.sender's address? No: fallback sends to msg.sender, so we want msg.sender to be the receiver contract to observe effect when transfer executes.
        // Therefore make the call originate from the receiver contract by letting it perform the call. But receiver must hold ETH to send; fund it.
        vm.deal(address(recv), 20 ether);

        // The helper will perform the low-level call to c.fallback by sending exactly 10 ether from its address
        bool ok = recv.callFallback{value: 0}(address(c));
        // Above we didn't send value from recv; instead have recv perform the call itself in its function.
        // After the call returns, we assert the universal property: c.pastBlockTime() equals the current block.timestamp
        // (Reference contract always stores pastBlockTime = block.timestamp at the end of a successful fallback that passed the require)

        // Single assertion reading c's public getter
        assertTrue(c.pastBlockTime() == block.timestamp);
    }
}

// Minimal helper that will act as the caller so that fallback's payable transfer to msg.sender goes to a contract (not an EOA).
contract Receiver {
    // Allow contract to receive ETH
    receive() external payable {}

    // Call C's fallback by performing a low-level call with exactly 10 ether
    function callFallback(address payable target) external payable returns (bool) {
        // send 10 ether with empty calldata to hit fallback
        (bool success, ) = target.call{value: 10 ether}("");
        return success;
    }
}

