contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz params: blockNumberMultiple selects whether block.number % 15 == 0 (via choosing a block number),
    // and attackerStartsWithBalance is an arbitrary value to seed the contract balance (kept wide).
    function testFuzz_property(uint256 warpTo, uint256 attackerStartsWithBalance) public {
        // keep warpTo reasonable but wide
        vm.assume(warpTo > 0 && warpTo < type(uint64).max);
        // Make block number a multiple of 15 to trigger the conditional branch in some runs.
        // We set the block number by rolling to a multiple of 15 close to warpTo.
        uint256 targetBlock = (warpTo / 15) * 15;
        if (targetBlock == 0) { targetBlock = 15; }
        vm.roll(uint64(targetBlock));

        // deploy attacker helper that will re-enter during transfer
        Attacker attacker = new Attacker(address(c));

        // fund attacker with some ETH so it can send 10 ether
        uint256 fund = 10 ether;
        if (attackerStartsWithBalance < fund) {
            vm.deal(address(this), fund);
            payable(address(attacker)).transfer(fund);
        } else {
            vm.deal(address(attacker), attackerStartsWithBalance);
        }

        // ensure contract has some initial balance to be drained on conditional transfer
        vm.deal(address(this), 1 ether);
        // seed c with extra balance so transfer(addr, balance) has something to drain
        payable(address(c)).transfer(1 ether);

        // set pastBlockTime to a time in the past so require(block.timestamp > pastBlockTime) holds
        vm.warp(block.timestamp - 1);

        // attacker will call fallback sending exactly 10 ether
        vm.prank(address(attacker));
        // attacker performs the call and inside its receive/fallback will reenter to drain if possible
        attacker.attack{value: 10 ether}();

        // After the call returns, the correct contract always updated pastBlockTime to block.timestamp.
        // We assert that; the mutant that defers the update and allows a reentrant drain can leave it unchanged.
        assertTrue(c.pastBlockTime() == block.timestamp);
    }
}

// Attacker that re-enters C during the payable fallback by receiving Ether and calling back into C
contract Attacker {
    address target;
    bool reentered;

    constructor(address _t) payable {
        target = _t;
    }

    // receive will be invoked when C transfers funds to msg.sender; we reenter C.fallback by sending 0 value call
    receive() external payable {
        if (!reentered) {
            reentered = true;
            // call fallback on C by sending a minimal call with 0 value; as fallback is payable, this triggers it
            // send exactly 0 value so requirement msg.value == 10 ether fails on reentry, but the mutant's ordering
            // means the transfer executed before pastBlockTime was stored; reentrancy is used to drain via transfer
            // we attempt to drain by calling payable with 0 - the important thing is to trigger transfer path in mutant
            (bool s,) = target.call("");
            s; // ignore
        }
    }

    // entry point: send exactly 10 ether to C.fallback
    function attack() external payable {
        // forward the call to C's fallback with exactly msg.value
        (bool ok,) = target.call{value: msg.value}("");
        require(ok);
    }
}

