pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: a timestamp delta to advance block time, and a block number offset
    // We fuzz a uint256 warpDelta (how much to advance timestamp) and a uint256 rollOffset (to reach a block %15==0)
    function testFuzz_property(uint256 warpDelta, uint256 rollOffset) public {
        // admissible domain:
        // warpDelta must be >0 so that block.timestamp > pastBlockTime (initial pastBlockTime is 0)
        vm.assume(warpDelta > 0 && warpDelta < 1 days);
        // rollOffset kept small to reach a block where number % 15 == 0 within a reasonable range
        rollOffset = bound(rollOffset, 0, 100);

        // deploy attacker which will re-enter during transfer to drain balance
        Attacker attacker = new Attacker(address(c));

        // fund attacker so it can send 10 ether
        uint256 sendAmt = 10 ether;
        vm.deal(address(attacker), sendAmt);

        // advance time by warpDelta so block.timestamp > pastBlockTime (pastBlockTime initial 0)
        vm.warp(block.timestamp + warpDelta);

        // advance block number to a block that is multiple of 15 so the conditional transfer triggers
        // find nearest future block where (block.number + k) % 15 == 0, with k in [0,100]
        uint256 cur = block.number;
        uint256 target = cur;
        bool found = false;
        for (uint256 k = 0; k <= rollOffset; ++k) {
            if ((cur + k) % 15 == 0) { target = cur + k; found = true; break; }
        }
        if (!found) {
            // if not found within bound, pick the next multiple within 100 steps
            uint256 k = (15 - (cur % 15)) % 15;
            target = cur + k;
        }
        vm.roll(target);

        // The attacker will receive the conditional transfer and reenter; make the attacker the msg.sender
        // and perform the payable call of exactly 10 ether
        address atk = address(attacker);
        vm.prank(atk);
        // call via low-level call to trigger fallback payable
        (bool ok, ) = atk.call{value: sendAmt}(abi.encodeWithSignature("callFallback(address)", address(c)));
        // we expect the call to return (fallback succeeded). For reference contract this must update pastBlockTime.
        // For the mutant, the attacker can drain balance during the transfer and cause pastBlockTime to remain old.

        // single assertion observing c: pastBlockTime equals current block.timestamp
        // note: block.timestamp is the time we warped to earlier
        assertTrue(c.pastBlockTime() == block.timestamp);
    }
}

