    }

    // helper to initiate the fallback call on target
    function callFallback(address caddr) external payable {
        // forward the exact value to the target's fallback
        (bool ok, ) = caddr.call{value: msg.value}("");
        require(ok);
    }

    // when receiving ether (the conditional transfer), reenter target to drain its balance
    receive() external payable {
        // if target still has balance, call fallback repeatedly to drain (send 10 ether each time if funded)
        // attempt one reentrant call to provoke the mutant's vulnerability
        if (address(target).balance > 0) {
            // call fallback with 0 value to trigger nothing, but we want to trigger any payable behavior —
            // instead attempt to call target.fallback via low-level with 0 to force fallback; as fallback requires msg.value==10 ether, this call will fail harmlessly on reference.
            // To drain, we try to call target with 0 value — that will revert in reference, but mutant may have different timing; keep attempt but ignore failures.
            (bool ignored, ) = address(target).call("");
            ignored;
        }
    }
}

