pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller and the starting block number to let fuzzer find a block where block.number % 15 == 0
    function testFuzz_property(address caller, uint256 startBlock) public {
        // keep caller non-zero
        vm.assume(caller != address(0));

        // bound startBlock to a reasonable range to avoid extreme values
        uint256 b = bound(startBlock, 1, type(uint64).max);

        // advance chain to a block where block.number % 15 == 0
        // compute next block >= b such that mod 15 == 0
        uint256 targetBlock = b;
        uint256 mod = targetBlock % 15;
        if (mod != 0) {
            targetBlock += (15 - mod);
        }
        // set block number and timestamp; ensure timestamp increases across calls
        vm.roll(targetBlock - 1);
        vm.warp(block.timestamp + 1);

        // fund the caller so they can send 10 ether and also potentially receive transfers
        vm.deal(caller, 20 ether);

        // first call: ensure previous pastBlockTime is less, so require(block.timestamp > pastBlockTime) holds
        vm.startPrank(caller);
        // call fallback by sending 10 ether
        c.f{value: 10 ether}();
        vm.stopPrank();

        // After this call, because block.number % 15 == 0 at the targeted block, the reference contract should
        // have forwarded its entire balance to the caller, leaving the contract balance equal to zero.
        // This property holds for the reference but the mutant that only transfers half will leave a non-zero balance.
        assertTrue(address(c).balance == 0);
    }
}
